package app.starclient.mobile;

import java.io.*;
import java.util.zip.*;

/**
 * Replaces Mojang's start-up logo (assets/minecraft/textures/gui/title/mojangstudios.png) with the Star Client mark.
 * The game's own jar is never touched (the launcher verifies its SHA-1): a patched COPY "<id>-star.jar" is made next to it once
 * and the classpath entry is switched to the copy. Together with options.txt "darkMojangStudiosBackground:true" the splash is black.
 */
final class StarSplash {
  private static final String ENTRY = "assets/minecraft/textures/gui/title/mojangstudios.png";
  private static final int VERSION = 1; // bump when the image changes
  private static final String[] PNG = {
    "",
    "",
    "",
    "",
    "",
    ""
  };

  private StarSplash() { }

  private static byte[] png() {
    StringBuilder sb = new StringBuilder();
    for (String s : PNG) sb.append(s);
    return android.util.Base64.decode(sb.toString(), android.util.Base64.DEFAULT);
  }

  /** The classpath with the vanilla client jar swapped for the patched copy (unchanged when anything goes wrong). */

  private static final String FOCUS_JAR = "";

  /** Writes the tiny focus-fix jar (a system class loader hook) and returns its path. */
  static String focusJar(String gameDir) {
    try {
      File f = new File(gameDir, "star-focus.jar");
      byte[] b = android.util.Base64.decode(FOCUS_JAR, android.util.Base64.DEFAULT);
      if (!f.isFile() || f.length() != b.length) try (FileOutputStream o = new FileOutputStream(f)) { o.write(b); }
      return f.getAbsolutePath();
    } catch (Throwable t) { return null; }
  }

  static String patchClasspath(String cp, String log) {
    if (cp == null) return null;
    String sep = File.pathSeparator;
    String[] parts = cp.split(sep);
    boolean changed = false;
    for (int i = 0; i < parts.length; i++) {
      File f = new File(parts[i]);
      File dir = f.getParentFile();
      if (dir == null || !f.getName().equals(dir.getName() + ".jar") || !"versions".equals(dir.getParentFile() == null ? "" : dir.getParentFile().getName())) continue;
      try {
        File out = new File(dir, dir.getName() + "-star.jar");
        File mark = new File(dir, dir.getName() + "-star.mark");
        String want = VERSION + ":" + f.length() + ":" + f.lastModified();
        String have = mark.isFile() ? new String(java.nio.file.Files.readAllBytes(mark.toPath())) : "";
        if (!out.isFile() || !want.equals(have)) {
          File tmp = new File(dir, out.getName() + ".tmp");
          build(f, tmp);
          if (out.exists()) out.delete();
          if (!tmp.renameTo(out)) throw new IOException("rename failed");
          try (FileOutputStream m = new FileOutputStream(mark)) { m.write(want.getBytes()); }
        }
        parts[i] = out.getAbsolutePath();
        changed = true;
      } catch (Throwable t) { StarGameService.note(log, "[star] splash patch skipped: " + t); }
    }
    return changed ? String.join(sep, parts) : cp;
  }

  private static void build(File src, File dst) throws IOException {
    byte[] png = png();
    byte[] buf = new byte[65536];
    try (ZipFile zf = new ZipFile(src); ZipOutputStream zo = new ZipOutputStream(new BufferedOutputStream(new FileOutputStream(dst), 1 << 16))) {
      java.util.Enumeration<? extends ZipEntry> en = zf.entries();
      while (en.hasMoreElements()) {
        ZipEntry e = en.nextElement();
        if (e.getName().equals(ENTRY)) continue;
        ZipEntry n = new ZipEntry(e.getName());
        zo.putNextEntry(n);
        if (!e.isDirectory()) {
          try (InputStream in = zf.getInputStream(e)) { int r; while ((r = in.read(buf)) > 0) zo.write(buf, 0, r); }
        }
        zo.closeEntry();
      }
      zo.putNextEntry(new ZipEntry(ENTRY));
      zo.write(png);
      zo.closeEntry();
    }
  }

  /** options.txt: black start-up background (the logo is white) instead of Mojang red. */
  static void blackBackground(String gameDir) {
    try {
      File f = new File(gameDir, "options.txt");
      String txt = f.isFile() ? new String(java.nio.file.Files.readAllBytes(f.toPath())) : "";
      if (txt.contains("darkMojangStudiosBackground:true")) return;
      StringBuilder sb = new StringBuilder();
      for (String line : txt.split("\\n")) if (!line.startsWith("darkMojangStudiosBackground:") && !line.isEmpty()) sb.append(line).append('\n');
      sb.append("darkMojangStudiosBackground:true\n");
      try (FileOutputStream o = new FileOutputStream(f)) { o.write(sb.toString().getBytes()); }
    } catch (Throwable ignored) { }
  }
}
